package com.shipflow.store;
import org.junit.jupiter.api.Test; import java.nio.file.*; import static org.assertj.core.api.Assertions.*;
class StoreMapperXmlTest { @Test void allStoreQueriesAreTenantScopedAndVersioned(){try{String xml=Files.readString(Path.of("src/main/resources/mapper/store/StoreMapper.xml"));assertThat(xml).contains("tenant_id=#{tenantId}","deleted=0","version=version+1","version=#{version}").doesNotContain("SELECT *");}catch(Exception e){throw new AssertionError(e);}} @Test void scopedReadsValidateCallerAndStoreAuthorization(){try{String xml=Files.readString(Path.of("src/main/resources/mapper/store/StoreMapper.xml"));assertThat(xml).contains("findByIdForUser","pageForUser","countForUser","countHistoricalOrders","sys_user_store_scope","sys_user_role","sys_role","MERCHANT_OPERATOR","MERCHANT_ADMIN","s.tenant_id=#{tenantId}");}catch(Exception e){throw new AssertionError(e);}} }
